function defaultPracticeCategories() {
  return [
    { id: "bcs-prelim", name: "বিসিএস প্রিলিমিনারী", icon: "🏛️", subjects: defaultPracticeSubjects() },
  ];
}

/** Migrates a pre-category save ({subjects, progress}) into the new
    {categories, progress} shape by wrapping the existing subject tree in
    a single "বিসিএস প্রিলিমিনারী" category — same subject/topic ids, so
    practice.progress (keyed subjectId::topicId) and any already-cached
    Edge Function/Storage question banks stay valid untouched. Runs once per browser,
    right after load; the migrated shape is what gets saved back. */
function migratePracticeStateToCategories(saved) {
  if (Array.isArray(saved.categories)) return saved; // already migrated
  if (Array.isArray(saved.subjects)) {
    return {
      categories: [{ id: "bcs-prelim", name: "বিসিএস প্রিলিমিনারী", icon: "🏛️", subjects: saved.subjects }],
      progress: saved.progress || {},
    };
  }
  return null;
}

function loadPracticeState() {
  try {
    const saved = JSON.parse(localStorage.getItem(PRACTICE_STORAGE_KEY) || "null");
    if (saved) {
      const migrated = migratePracticeStateToCategories(saved);
      if (migrated) return migrated;
    }
  } catch (e) { /* fall through to defaults */ }
  return { categories: defaultPracticeCategories(), progress: {} };
}
let practiceState = loadPracticeState();
// Which category the Practice Panel / Admin Panel is currently drilled
// into. Transient nav state only — never persisted, never read by
// anything outside the Practice Panel/Admin Panel/Statistics UI layer.
// Defaults to the first category so existing single-category users land
// exactly where they used to (straight into the subject list).
let activePracticeCategoryId = (practiceState.categories[0] || {}).id || null;
function getActivePracticeCategory() {
  return practiceState.categories.find((c) => c.id === activePracticeCategoryId) || practiceState.categories[0] || null;
}
/** Live reference to the active category's subjects array — every Admin
    Panel/AGQ read AND write (push/filter/reassign) goes through this so
    edits land on the right category object instead of a detached copy.
    Falls back to an empty array only if there is truly no category yet
    (e.g. every category was deleted), so Admin Panel code that calls
    .map/.find/.length on the result never throws. */
function getPracticeAdminSubjects() {
  const category = getActivePracticeCategory();
  return category ? category.subjects : [];
}
function setPracticeAdminSubjects(subjects) {
  const category = getActivePracticeCategory();
  if (category) category.subjects = subjects;
}
function practiceCategoryId() { return "pc" + Date.now().toString(36) + Math.random().toString(36).slice(2, 6); }
// Local cache only from here on — see refreshPracticeManifest() below for
// the real source of truth (the Worker/KV manifest). localStorage is kept
// so the Practice Panel still has *something* to show instantly on load
// and while offline, before the network fetch resolves.
function savePracticeState() {
  localStorage.setItem(PRACTICE_STORAGE_KEY, JSON.stringify(practiceState));
}

/* ---------- Subject/Topic manifest sync (Worker/KV) ----------
   The Subject/Topic tree used to live only in each browser's localStorage
   (see defaultPracticeSubjects() above), which meant anything the admin
   created never reached students — their browsers just built their own
   default list independently and the ids never matched what the admin
   had pushed questions into. GET/PUT /api/practice/manifest (added to
   worker.js alongside this change) makes the tree itself a synced
   resource, the same way question content already was.

   Categories-aware as of this update: the manifest now carries the full
   {categories:[{id,name,icon,subjects}]} shape practiceState actually
   uses, not just a flat subjects[] list. fetchPracticeManifest() still
   accepts an older flat-shape response from a not-yet-upgraded Worker
   (wraps it into a single default category) so this doesn't hard-break
   against worker.js before its /api/practice/manifest route is updated
   to return {categories: [...]} — update worker.js to return that shape
   directly once convenient; this fallback can be removed after. */

/** Fetches the current category/Subject/Topic tree from the Worker.
    Accepts either the current {categories:[...]} response or a legacy
    {subjects:[...]} response from an older Worker deployment (wrapped
    into a single "বিসিএস প্রিলিমিনারী" category so callers only ever
    handle one shape). Throws on network/HTTP failure so callers can
    decide how to degrade (see refreshPracticeManifest). */
async function fetchPracticeManifest() {
  const res = await fetch(`${PRACTICE_API_BASE}/practice/manifest`);
  if (!res.ok) throw new Error(`Practice API returned ${res.status}`);
  const data = await res.json();
  if (Array.isArray(data.categories)) return data.categories;
  if (Array.isArray(data.subjects)) {
    // Legacy flat-shape Worker response — wrap it so callers still get
    // the categories[] shape practiceState now expects.
    return [{ id: "bcs-prelim", name: "বিসিএস প্রিলিমিনারী", icon: "🏛️", subjects: data.subjects }];
  }
  return [];
}

/** Overwrites the full category/Subject/Topic tree on the Worker.
    Admin-only (the Worker checks the Firebase ID token); only sends
    id/name/icon/topics/language — never question content, which stays
    per-topic in its own KV entry via pushPracticeTopicQuestions. */
async function pushPracticeManifest(categories) {
  if (!isSignedIn()) throw new Error("Not signed in.");
  const idToken = await firebase.auth().currentUser.getIdToken();
  const slim = categories.map((c) => ({
    id: c.id,
    name: c.name,
    icon: c.icon || "",
    subjects: (c.subjects || []).map((s) => ({
      id: s.id,
      name: s.name,
      mainTopics: s.mainTopics || [],
      topics: (s.topics || []).map((t) => ({ id: t.id, name: t.name, language: t.language || "en", mainTopicId: t.mainTopicId || null })),
    })),
  }));
  const res = await fetch(`${PRACTICE_API_BASE}/practice/manifest`, {
    method: "PUT",
    headers: { "Content-Type": "application/json", "Authorization": `Bearer ${idToken}` },
    body: JSON.stringify({ categories: slim }),
  });
  if (!res.ok) throw new Error(`Practice API returned ${res.status}`);
  return res.json();
}

/** Pulls the latest manifest from the Worker and merges it into
    practiceState, keeping each topic's already-cached `language` in
    memory intact and remapping any already-saved progress whose
    subject/topic id changed (same name, new id) so a re-sync never
    silently orphans a student's practice history. Called once at
    startup (see the call site right after practiceState is first
    read) and after every admin edit that changes the tree (see
    syncPracticeManifestAfterEdit). Fails soft: on any network/HTTP
    error the existing localStorage-cached practiceState is left
    exactly as it was (same offline-first behavior the rest of this
    app already relies on), and this returns false so callers know
    the sync didn't happen. */
async function refreshPracticeManifest() {
  try {
    const remoteCategories = await fetchPracticeManifest();
    if (!Array.isArray(remoteCategories) || remoteCategories.length === 0) return false;

    // Build old-id -> {name, language} lookups per category before
    // overwriting, so progress keyed on an id that changed server-side
    // (same subject/topic name, new id) can be remapped instead of lost.
    const oldLookup = new Map(); // "categoryId::name::name" -> { oldSubjectId, oldTopicId, language }
    practiceState.categories.forEach((cat) => {
      (cat.subjects || []).forEach((s) => {
        (s.topics || []).forEach((tp) => {
          oldLookup.set(`${cat.id}::${s.name}::${tp.name}`, { oldSubjectId: s.id, oldTopicId: tp.id, language: tp.language });
        });
      });
    });

    const remapped = {}; // newProgressKey -> oldProgressKey, applied after
    const newCategories = remoteCategories.map((cat) => ({
      id: cat.id,
      name: cat.name,
      icon: cat.icon || "🏛️",
      subjects: (cat.subjects || []).map((s) => ({
        id: s.id,
        name: s.name,
        mainTopics: s.mainTopics || [],
        topics: (s.topics || []).map((tp) => {
          const prior = oldLookup.get(`${cat.id}::${s.name}::${tp.name}`);
          const newKey = practiceProgressKey(s.id, tp.id);
          if (prior && (prior.oldSubjectId !== s.id || prior.oldTopicId !== tp.id)) {
            remapped[newKey] = practiceProgressKey(prior.oldSubjectId, prior.oldTopicId);
          }
          return { id: tp.id, name: tp.name, questions: [], language: (prior && prior.language) || tp.language || "en", mainTopicId: tp.mainTopicId || null };
        }),
      })),
    }));

    Object.entries(remapped).forEach(([newKey, oldKey]) => {
      if (practiceState.progress[oldKey] && !practiceState.progress[newKey]) {
        practiceState.progress[newKey] = practiceState.progress[oldKey];
      }
    });

    // The remap above only updated practiceState.progress (localStorage).
    // Without also queuing a cloud write under the new subject/topic id,
    // Supabase keeps the row under the old id forever — so a login on a
    // different device (or a cleared localStorage here) pulls the old,
    // pre-remap key and the "migrated" progress looks lost. Push each
    // remapped entry under its new key the same way any other practice
    // answer would be queued.
    Object.entries(remapped).forEach(([newKey]) => {
      const entry = practiceState.progress[newKey];
      if (!entry) return;
      const [newSubjectId, newTopicId] = newKey.split("::");
      queuePracticeProgressWrite(newSubjectId, newTopicId, entry);
    });

    practiceState.categories = newCategories;
    if (!newCategories.find((c) => c.id === activePracticeCategoryId)) {
      activePracticeCategoryId = (newCategories[0] || {}).id || null;
    }
    savePracticeState();
    return true;
  } catch (e) {
    console.warn("[Practice] Manifest sync failed, staying on cached localStorage data:", e.message);
    return false;
  }
}

/** Pushes the current in-memory practiceState.categories tree to the
    Worker after an admin edit (add/rename/delete subject or topic,
    category CRUD). Fire-and-forget from the caller's perspective —
    failures are logged and toasted, not thrown, so a temporarily
    unreachable Worker never blocks the local edit the admin just made;
    savePracticeState() (called by every edit site already) keeps that
    edit safe in localStorage regardless of whether this sync succeeds. */
async function syncPracticeManifestAfterEdit() {
  try {
    await pushPracticeManifest(practiceState.categories);
  } catch (e) {
    console.warn("[Practice] Failed to sync manifest to server:", e.message);
    if (typeof showToast === "function") {
      showToast("সাবজেক্ট/টপিক তালিকা সার্ভারে সিঙ্ক করা যায়নি — এই ডিভাইসে সংরক্ষিত আছে।", "warning");
    }
  }
}

function findPracticeTopic(subjectId, topicId) {
  const category = getActivePracticeCategory();
  const subject = (category ? category.subjects : []).find((s) => s.id === subjectId);
  if (!subject) return null;
  const topic = subject.topics.find((t) => t.id === topicId);
  if (!topic) return null;
  return { subject, topic };
}
function practiceProgressKey(subjectId, topicId) { return `${subjectId}::${topicId}`; }

/* ---------- Practice Panel: category grid → subject accordion ---------- */
registerGlobalDropdown("practice-panel-accordion", () => {
  qsa(".pp-subject.is-open", qs("#pp-subject-list") || document).forEach((el) => {
    el.classList.remove("is-open");
    const h = el.querySelector("[data-subject-toggle]");
    if (h) h.setAttribute("aria-expanded", "false");
  });
});

/** Top-level screen of the Practice Panel (#view-practice): one card per
    exam category (বিসিএস প্রিলিমিনারী, ব্যাংক প্রিলিমিনারী, ...) — cards
    only, no subject list on this screen. Picking a card navigates to the
    separate #view-practice-subjects view (see navigateToPracticeSubjects
    below) for that category's Subject/Topic accordion. */
function renderPracticeCategoryList() {
  const container = qs("#pp-category-list");
  if (!container) return;
  const adminEntry = qs("#practice-admin-entry");
  if (adminEntry) adminEntry.hidden = !(isPracticeAdmin() || isLiveExamAdmin());

  const categories = practiceState.categories || [];
  container.innerHTML = categories.length
    ? categories.map((cat) => {
        const iconHtml = cat.icon && cat.icon.startsWith("data:image")
          ? `<img class="pp-category-card__icon pp-category-card__icon--img" src="${escapeHtml(cat.icon)}" alt="" />`
          : `<span class="pp-category-card__icon">${escapeHtml(cat.icon || "📚")}</span>`;
        return `
      <button type="button" class="pp-category-card" data-practice-category="${escapeHtml(cat.id)}">
        ${iconHtml}
        <span class="pp-category-card__name">${escapeHtml(cat.name)}</span>
        ${cat.description ? `<span class="pp-category-card__desc">${escapeHtml(cat.description)}</span>` : ""}
      </button>`;
      }).join("")
    : `<div class="pp-subject__empty" data-i18n="practice.category.empty">${escapeHtml(t("practice.category.empty"))}</div>`;

  qsa("[data-practice-category]", container).forEach((btn) => {
    btn.addEventListener("click", () => {
      activePracticeCategoryId = btn.getAttribute("data-practice-category");
      navigateToView("practice-subjects");
    });
  });
}

/** Drill-down screen (#view-practice-subjects): the Subject/Topic
    accordion for whichever category was picked on the category grid —
    same markup/behavior as before categories existed, just scoped to
    getActivePracticeCategory() and living in its own view/history entry
    instead of a hidden-toggle inside #view-practice. */
function renderPracticeSubjectList() {
  const container = qs("#pp-subject-list");
  const pageLabel = qs("#pp-subjects-page-label");
  const heading = qs("#pp-subjects-heading");
  if (!container) return;
  const category = getActivePracticeCategory();
  if (!category) { navigateToView("practice"); return; }

  if (pageLabel) pageLabel.textContent = category.name;
  if (heading) {
    const iconHtml = category.icon && category.icon.startsWith("data:image")
      ? `<img class="pp-subjects-heading__icon pp-subjects-heading__icon--img" src="${escapeHtml(category.icon)}" alt="" />`
      : `<span class="pp-subjects-heading__icon">${escapeHtml(category.icon || "📚")}</span>`;
    heading.innerHTML = `${iconHtml}<span class="pp-subjects-heading__name">${escapeHtml(category.name)}</span>`;
  }

  container.innerHTML = category.subjects.map((subject) => {
    const topicRow = (topic) => `
          <button type="button" class="pp-topic-row" data-practice-topic data-subject-id="${escapeHtml(subject.id)}" data-topic-id="${escapeHtml(topic.id)}">
            <span class="pp-topic-row__name">${escapeHtml(topic.name)}</span>
          </button>`;
    const mainTopics = subject.mainTopics || [];
    const groupsHtml = mainTopics.map((main) => {
      const inGroup = subject.topics.filter((t) => t.mainTopicId === main.id);
      return `
        <div class="pp-main">
          <button type="button" class="pp-main__head" data-main-toggle aria-expanded="false">
            <span class="pp-main__name">${escapeHtml(main.name)}</span>
            <svg class="pp-main__chevron" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M6 9l6 6 6-6"/></svg>
          </button>
          <div class="pp-main__collapse">
            <div class="pp-main__topics">${inGroup.map(topicRow).join("") || `<div class="pp-subject__empty">No topics yet</div>`}</div>
          </div>
        </div>`;
    }).join("");
    const ungrouped = subject.topics.filter((t) => !mainTopics.some((m) => m.id === t.mainTopicId));
    const topicsHtml = (groupsHtml + ungrouped.map(topicRow).join("")) || `<div class="pp-subject__empty">No topics yet</div>`;
    return `
    <section class="pp-subject" data-subject-card="${escapeHtml(subject.id)}">
      <button type="button" class="pp-subject__head" data-subject-toggle="${escapeHtml(subject.id)}" aria-expanded="false">
        <div class="pp-subject__title-wrap">
          <div class="pp-subject__title">${escapeHtml(subject.name)}</div>
        </div>
        <svg class="pp-subject__chevron" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M6 9l6 6 6-6"/></svg>
      </button>
      <div class="pp-subject__topics">
        <div class="pp-subject__topics-clip">
          <div class="pp-subject__topics-inner">${topicsHtml}</div>
        </div>
      </div>
    </section>`;
  }).join("");

  qsa("[data-subject-toggle]", container).forEach((btn) => {
    btn.addEventListener("click", () => {
      const card = btn.closest(".pp-subject");
      if (!card) return;
      const willOpen = !card.classList.contains("is-open");
      if (willOpen) {
        closeOtherGlobalDropdowns("practice-panel-accordion");
        qsa(".pp-subject.is-open", container).forEach((el) => {
          el.classList.remove("is-open");
          const h = el.querySelector("[data-subject-toggle]");
          if (h) h.setAttribute("aria-expanded", "false");
        });
      }
      card.classList.toggle("is-open", willOpen);
      btn.setAttribute("aria-expanded", willOpen ? "true" : "false");
    });
  });
  qsa("[data-main-toggle]", container).forEach((btn) => {
    btn.addEventListener("click", () => {
      const group = btn.closest(".pp-main");
      const open = group.classList.toggle("is-open");
      btn.setAttribute("aria-expanded", open ? "true" : "false");
    });
  });
  qsa("[data-practice-topic]", container).forEach((btn) => {
    btn.addEventListener("click", () => {
      const subjectId = btn.getAttribute("data-subject-id");
      const topicId = btn.getAttribute("data-topic-id");
      openPracticeInterestModal(subjectId, topicId);
    });
  });
}



/* ---------- Practice: Select-your-interest popup (Evaluate / Practice) ----------
   Opened on every topic tap in the Practice Panel instead of jumping
   straight into Practice Mode. Both branches re-fetch the topic's
   question bank themselves (Evaluate needs the full bank to shuffle/
   split into modules; Practice hands off to the unchanged
   enterPracticeMode, which does its own fetch) rather than caching it
   here, keeping this function a thin dispatcher. */
/* Topic tap: if the topic's questions carry subtopic names, first ask
   which subtopic to practise; otherwise go straight to the interest popup
   exactly as before. */
async function openPracticeTopicEntry(subjectId, topicId) {
  let questions = [];
  try {
    questions = await getPracticeTopicQuestions(subjectId, topicId);
  } catch (e) {
    console.error(e);
    openPracticeInterestModal(subjectId, topicId);
    return;
  }
  const counts = new Map();
  questions.forEach((q) => {
    const name = (q.subtopic || "").trim();
    if (name) counts.set(name, (counts.get(name) || 0) + 1);
  });
  if (counts.size === 0) { openPracticeInterestModal(subjectId, topicId); return; }
  openPracticeSubtopicPicker(subjectId, topicId, questions.length, counts);
}

function openPracticeSubtopicPicker(subjectId, topicId, total, counts) {
  let overlay = document.getElementById("practice-subtopic-modal");
  if (!overlay) {
    overlay = document.createElement("div");
    overlay.className = "modal-overlay";
    overlay.id = "practice-subtopic-modal";
    overlay.setAttribute("aria-hidden", "true");
    overlay.innerHTML = `
      <div class="modal" role="dialog" aria-modal="true" aria-labelledby="practice-subtopic-title">
        <div class="modal__header">
          <h2 id="practice-subtopic-title" class="text-h3">Choose subtopic</h2>
          <button type="button" class="icon-btn" data-subtopic-close aria-label="Close">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"/></svg>
          </button>
        </div>
        <div class="modal__body" id="practice-subtopic-list" style="display: flex; flex-direction: column; gap: var(--space-2);"></div>
      </div>`;
    document.body.appendChild(overlay);
    overlay.addEventListener("click", (e) => { if (e.target === overlay) closeModal("practice-subtopic-modal"); });
    qs("[data-subtopic-close]", overlay).addEventListener("click", () => closeModal("practice-subtopic-modal"));
  }
  const list = document.getElementById("practice-subtopic-list");
  const rows = [{ key: "", label: "All questions", count: total }]
    .concat([...counts.entries()].map(([name, count]) => ({ key: name, label: name, count })));
  list.innerHTML = rows.map((r, i) => `
    <button type="button" class="btn btn-outline" data-subtopic-index="${i}" style="justify-content: space-between; width: 100%;">
      <span>${escapeHtml(r.label)}</span><span class="text-muted">${r.count}</span>
    </button>`).join("");
  qsa("[data-subtopic-index]", list).forEach((btn) => {
    btn.addEventListener("click", () => {
      const pick = rows[Number(btn.getAttribute("data-subtopic-index"))];
      closeModal("practice-subtopic-modal");
      // Wait for closeModal's history step to settle before opening the next popup.
      setTimeout(() => openPracticeInterestModal(subjectId, topicId, pick.key || null), 80);
    });
  });
  openModal("practice-subtopic-modal");
}

let practiceInterestTarget = null; // { subjectId, topicId, subject, topic }

function openPracticeInterestModal(subjectId, topicId, subtopic = null) {
  const found = findPracticeTopic(subjectId, topicId);
  if (!found) { showToast("This topic isn't available.", "danger"); return; }
  practiceInterestTarget = { subjectId, topicId, subject: found.subject, topic: found.topic, subtopic: subtopic || null };
  // Evaluate works on the whole topic bank, so it is hidden for a subtopic.
  const evalBtnEl = qs("#practice-interest-evaluate-btn");
  if (evalBtnEl) evalBtnEl.hidden = !!subtopic;
  const subjectEl = qs("#practice-interest-modal-subject");
  const topicEl = qs("#practice-interest-modal-topic");
  if (subjectEl) subjectEl.textContent = found.subject.name;
  if (topicEl) topicEl.textContent = found.topic.name;
  openModal("practice-interest-modal");
}

function initPracticeInterestModal() {
  const evaluateBtn = qs("#practice-interest-evaluate-btn");
  const practiceBtn = qs("#practice-interest-practice-btn");
  if (evaluateBtn) {
    evaluateBtn.addEventListener("click", async () => {
      if (!practiceInterestTarget) return;
      const { subjectId, topicId } = practiceInterestTarget;
      closeModal("practice-interest-modal");
      await openPracticeModuleModal(subjectId, topicId);
    });
  }
  if (practiceBtn) {
    practiceBtn.addEventListener("click", () => {
      if (!practiceInterestTarget) return;
      const { subjectId, topicId } = practiceInterestTarget;
      closeModal("practice-interest-modal");
      enterPracticeMode(subjectId, topicId, practiceInterestTarget.subtopic);
    });
  }
}

/* ---------- Practice: Evaluate — module split + module-select popup ----------
   No difficulty tagging exists on practice-bank questions, so modules
   are formed by shuffling the full bank once (Fisher–Yates) and
   slicing it into fixed EVALUATE_MODULE_SIZE chunks in order — every
   question lands in exactly one module (no repeats across modules,
   see the user's spec), and each module ends up with a natural mix of
   difficulties since the source order is randomized first. The final
   module simply gets whatever remains (may be smaller, or the only
   module if the bank has fewer than EVALUATE_MODULE_SIZE questions). */
const EVALUATE_MODULE_SIZE = 50;
const EVALUATE_MODULE_DURATION_MINUTES = 30;

function shuffleArray(arr) {
  const out = arr.slice();
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [out[i], out[j]] = [out[j], out[i]];
  }
  return out;
}

function buildEvaluateModules(questions) {
  const shuffled = shuffleArray(questions);
  const modules = [];
  for (let i = 0; i < shuffled.length; i += EVALUATE_MODULE_SIZE) {
    modules.push(shuffled.slice(i, i + EVALUATE_MODULE_SIZE));
  }
  return modules;
}

async function openPracticeModuleModal(subjectId, topicId) {
  const found = findPracticeTopic(subjectId, topicId);
  if (!found) { showToast("This topic isn't available.", "danger"); return; }
  const { subject, topic } = found;

  let questions;
  try {
    questions = await getPracticeTopicQuestions(subjectId, topicId);
  } catch (e) {
    console.error(e);
    showToast("Couldn't load this topic's questions. Check your connection and try again.", "danger");
    return;
  }
  if (!questions.length) {
    showToast("No questions have been added to this topic yet.", "info");
    return;
  }

  const modules = buildEvaluateModules(questions);
  const subjectEl = qs("#practice-module-modal-subject");
  const topicEl = qs("#practice-module-modal-topic");
  if (subjectEl) subjectEl.textContent = subject.name;
  if (topicEl) topicEl.textContent = topic.name;

  const list = qs("#practice-module-modal-list");
  if (list) {
    list.innerHTML = modules.map((mod, i) => `
      <button type="button" class="btn btn-outline btn-lg evaluate-module-btn" data-evaluate-module-index="${i}">
        <span class="evaluate-module-btn__title">Module ${i + 1}</span>
        <span class="evaluate-module-btn__meta">${mod.length} questions</span>
      </button>`).join("");
    qsa("[data-evaluate-module-index]", list).forEach((btn) => {
      btn.addEventListener("click", () => {
        const idx = Number(btn.getAttribute("data-evaluate-module-index"));
        closeModal("practice-module-modal");
        startEvaluateModule(subject, topic, modules[idx], idx + 1);
      });
    });
  }

  openModal("practice-module-modal");
}

/** Launches one Evaluate module into the existing Exam Mode player —
    same shape as buildExamFromLiveExam, tagged with practiceEvalId
    (instead of liveExamId) so submitExam()/history can tell an
    Evaluate attempt apart from a Live Exam or AI-generated one without
    touching either of those paths. Duration/marking follow the
    student's own Evaluate spec (30 min/module) and the site's default
    exam marking prefs, same as a regular AI Mode exam. */
function startEvaluateModule(subject, topic, moduleQuestions, moduleNumber) {
  const prefs = getStoredExamPrefs();
  const questions = moduleQuestions.map((q, i) => {
    const clean = sanitizeQuestionMath(q);
    return {
      id: `question-${i + 1}`,
      question: clean.question, options: clean.options,
      correctAnswer: clean.correctAnswer, explanation: clean.explanation || "",
    };
  });
  const exam = {
    examId: genId("exam"),
    practiceEvalId: `${subject.id}::${topic.id}::module-${moduleNumber}`,
    subject: subject.name, topic: `${topic.name} (Module ${moduleNumber})`,
    language: topic.language || "en",
    questionCount: questions.length,
    duration: EVALUATE_MODULE_DURATION_MINUTES,
    marksPerQuestion: 1,
    negativeMarking: prefs.negativeMarkValue ?? 0.25,
    questions,
  };
  createExamSession(exam);
  showToast("Starting your evaluation - this reuses your existing Exam Mode player.", "success");
  showView("exam", { resetHistory: true });
  enterEvaluateExam();
}

function enterEvaluateExam() {
  const session = restoreExamSession();
  if (!session) { showToast("No active exam found.", "danger"); showView("home"); return; }
  if (session.status === "completed") { enterStatistics(); return; }
  liveExamState.session = session;

  const exam = session.exam;
  qs("#header-subject").textContent = exam.subject || "Exam";
  qs("#header-topic").textContent = exam.topic || "";

  showView("exam");
  renderQuestionStream();
  renderNavigator();
  renderQuestion();
  startTimer();
  initMobileNavStripSync();
}

/* ---------- Practice Mode: Exam-Mode-styled runner ---------- */
let practiceModeState = null; // { subjectId, topicId, questions, answers: {qId: idx}, current }

async function enterPracticeMode(subjectId, topicId, subtopic = null) {
  const found = findPracticeTopic(subjectId, topicId);
  if (!found) { showToast("This topic isn't available.", "danger"); return; }
  const { subject, topic } = found;

  // Question content now lives in Supabase Storage (see getPracticeTopicQuestions), not
  // on the local topic object, so this is a network call — show a toast
  // if it's slow/fails rather than leaving the button looking unresponsive.
  let questions;
  try {
    questions = await getPracticeTopicQuestions(subjectId, topicId);
  } catch (e) {
    console.error(e);
    showToast("Couldn't load this topic's questions. Check your connection and try again.", "danger");
    return;
  }
  if (subtopic) questions = questions.filter((q) => (q.subtopic || "").trim() === subtopic);
  if (!questions.length) {
    showToast("No questions have been added to this topic yet.", "info");
    return;
  }

  // A subtopic session keeps its own run in memory only, so it never
  // overwrites or mixes with the whole-topic saved progress.
  const savedProgress = subtopic ? null : practiceState.progress[practiceProgressKey(subjectId, topicId)];
  practiceModeState = {
    subjectId,
    topicId,
    subtopic: subtopic || null,
    subjectName: subject.name,
    topicName: topic.name,
    language: topic.language || "en",
    questions,
    answers: (savedProgress && savedProgress.answers) ? { ...savedProgress.answers } : {},
    current: (savedProgress && typeof savedProgress.current === "number") ? savedProgress.current : 0,
  };

  qs("#pm-header-subject").textContent = subject.name;
  qs("#pm-header-topic").textContent = topic.name;

  showView("practice-mode");
  renderPracticeQuestionStream();
  renderPracticeNavigator();
  updatePracticeScorePill();
  goToPracticeQuestionCard(practiceModeState.current, { skipSave: true });
  initPracticeMobileNavStripSync();
}

function savePracticeProgress() {
  if (!practiceModeState || practiceModeState.subtopic) return;
  const { subjectId, topicId } = practiceModeState;
  const key = practiceProgressKey(subjectId, topicId);
  const answeredCount = Object.keys(practiceModeState.answers).length;
  const entry = {
    answers: { ...practiceModeState.answers },
    current: practiceModeState.current,
    answeredCount,
    updatedAt: Date.now(),
  };
  practiceState.progress[key] = entry;
  savePracticeState();
  // Mirrors upsertExamHistory's pattern below: local write is always the
  // synchronous source of truth (Statistics/BCS-Preliminary charts read
  // practiceState.progress directly and must never wait on a network
  // round-trip), the cloud write is fire-and-forget on top of it.
  queuePracticeProgressWrite(subjectId, topicId, entry);
}

function practiceQuestionOutcome(q, selectedIdx) {
  if (selectedIdx === undefined) return "unanswered";
  return selectedIdx === q.correctAnswer ? "correct" : "wrong";
}

function renderPracticeQuestionStream() {
  const s = practiceModeState;
  const stream = qs("#pm-question-stream");
  stream.innerHTML = "";
  // Question number badge (০১, ০২...) and option markers (ক/খ/গ/ঘ) follow
  // THIS topic's own language — set by the admin's builder-tab EN/বাংলা
  // toggle when the questions were pushed (see PracticeMCQBuilder.pushQuestions)
  // — not the site-wide EN/বাংলা toggle, so each topic renders consistently
  // for every student regardless of their own UI language preference.
  const useLocalized = usesLocalizedLabels(s.language);
  const letters = optionLetters(useLocalized);

  s.questions.forEach((q, index) => {
    const card = document.createElement("div");
    card.className = "card question-card";
    card.id = `pm-q-card-${index}`;
    card.dataset.index = String(index);

    const head = document.createElement("div");
    head.className = "question-card__head";

    const heading = document.createElement("h2");
    heading.className = "question-text";
    heading.id = `pm-question-text-${index}`;
    const numBadge = document.createElement("span");
    numBadge.className = "question-card__num";
    numBadge.textContent = formatQuestionNumber(index, useLocalized);
    heading.appendChild(numBadge);
    heading.appendChild(document.createTextNode(q.question));
    head.appendChild(heading);
    card.appendChild(head);

    const list = document.createElement("div");
    list.id = `pm-options-list-${index}`;
    list.setAttribute("role", "radiogroup");
    list.setAttribute("aria-labelledby", `pm-question-text-${index}`);

    q.options.forEach((optionText, idx) => {
      const row = document.createElement("label");
      row.className = "option";
      row.innerHTML = `<span class="option__letter">${letters[idx]}</span><span class="option__text"></span>`;
      row.querySelector(".option__text").textContent = optionText;
      row.addEventListener("click", (e) => {
        e.preventDefault();
        if (s.answers[q.id] !== undefined) return; // already answered — locked
        selectPracticeAnswer(index, idx);
      });
      list.appendChild(row);
    });
    card.appendChild(list);

    const explanation = document.createElement("div");
    explanation.className = "pm-explanation";
    explanation.id = `pm-explanation-${index}`;
    explanation.hidden = true;
    if (q.explanation) {
      explanation.innerHTML = `<span class="pm-explanation__label"></span><span></span>`;
      explanation.querySelector("span:last-child").textContent = q.explanation;
    }
    card.appendChild(explanation);

    stream.appendChild(card);
    renderMathIn(card);
  });

  updateAllPracticeQuestionCards();
}

function updatePracticeQuestionCard(index, animate) {
  const s = practiceModeState;
  const q = s.questions[index];
  const card = qs(`#pm-q-card-${index}`);
  if (!card) return;
  const selected = s.answers[q.id];
  const outcome = practiceQuestionOutcome(q, selected);

  qsa(".option", qs(`#pm-options-list-${index}`)).forEach((row, idx) => {
    row.classList.remove("pm-correct", "pm-wrong", "is-locked");
    const existingTag = row.querySelector(".option__tag");
    if (existingTag) existingTag.remove();
    if (outcome === "unanswered") return;
    row.classList.add("is-locked");
    const isCorrectOpt = idx === q.correctAnswer;
    const isSelectedOpt = idx === selected;
    if (isCorrectOpt) row.classList.add("pm-correct");
    else if (isSelectedOpt && outcome === "wrong") row.classList.add("pm-wrong");
    if (isCorrectOpt || (isSelectedOpt && outcome === "wrong")) {
      const tag = document.createElement("span");
      tag.className = "option__tag" + (animate ? " option__tag--animate" : "");
      tag.textContent = isCorrectOpt ? "✓" : "✕";
      row.appendChild(tag);
    }
  });

  const explanation = qs(`#pm-explanation-${index}`);
  if (explanation) {
    const shouldShow = outcome !== "unanswered" && !!q.explanation;
    if (!animate) {
      // Plain re-render (page load, navigating back to an already
      // -answered question, jumping between cards) — no transition,
      // just the right end state straight away. Also clears any leftover
      // inline max-height from a previous animated open (see the
      // transitionend handler below) so it doesn't override the
      // collapsed/opening classes' own max-height next time this
      // question *is* animated.
      explanation.style.maxHeight = "";
      explanation.hidden = !shouldShow;
      explanation.classList.remove("pm-explanation--collapsed", "pm-explanation--opening");
    } else if (shouldShow) {
      // Fresh answer just picked — play the drop-down. `hidden` has to
      // come off (and the element has to actually paint once in its
      // collapsed state) before adding --opening, or the browser has no
      // "before" state to transition from and the box just snaps open.
      explanation.style.maxHeight = "";
      explanation.hidden = false;
      explanation.classList.add("pm-explanation--collapsed");
      explanation.classList.remove("pm-explanation--opening");
      requestAnimationFrame(() => {
        requestAnimationFrame(() => {
          explanation.classList.add("pm-explanation--opening");
        });
      });
      // pm-explanation--opening's max-height (400px) is only a transition
      // target, not a real content cap — a longer explanation would stay
      // clipped after the animation ends otherwise. Once the transition
      // finishes, drop max-height entirely so any length of text is
      // fully visible. { once: true } means this doesn't need manual
      // cleanup or interfere with the next question's animation.
      explanation.addEventListener("transitionend", function onOpen(e) {
        if (e.propertyName !== "max-height") return;
        explanation.style.maxHeight = "none";
      }, { once: true });
    } else {
      explanation.hidden = true;
      explanation.classList.remove("pm-explanation--collapsed", "pm-explanation--opening");
    }
  }

  card.classList.toggle("is-current", index === s.current);
}
function updateAllPracticeQuestionCards() {
  practiceModeState.questions.forEach((_, index) => updatePracticeQuestionCard(index));
}

function selectPracticeAnswer(index, optionIdx) {
  const s = practiceModeState;
  const q = s.questions[index];
  s.answers[q.id] = optionIdx;
  updatePracticeQuestionCard(index, /* animate */ true);
  updatePracticeScorePill();
  renderPracticeNavigator();
  savePracticeProgress();
}

function updatePracticeScorePill() {
  const s = practiceModeState;
  let right = 0, wrong = 0;
  s.questions.forEach((q) => {
    const outcome = practiceQuestionOutcome(q, s.answers[q.id]);
    if (outcome === "correct") right++;
    else if (outcome === "wrong") wrong++;
  });
  qs("#pm-right-count").textContent = String(right);
  qs("#pm-wrong-count").textContent = String(wrong);
}

function practiceQuestionNavClasses(s, q, index) {
  const outcome = practiceQuestionOutcome(q, s.answers[q.id]);
  return "pm-q-btn q-btn" + (index === s.current ? " is-current" : "") + (outcome === "correct" ? " pm-correct" : outcome === "wrong" ? " pm-wrong" : "");
}

function renderPracticeNavigator() {
  const s = practiceModeState;
  const grid = qs("#pm-question-nav-grid");
  const strip = qs("#pm-mobile-nav-strip");
  const expectedCount = s.questions.length;

  // Same in-place-update fast path as renderNavigator() (Exam Mode): avoid
  // rebuilding the DOM on every answer/navigation so the smooth-scroll
  // animation isn't interrupted by a reflow.
  const gridBuilt = grid.children.length === expectedCount;
  const stripBuilt = !strip || strip.children.length === expectedCount;
  if (gridBuilt && stripBuilt) {
    s.questions.forEach((q, index) => {
      const cls = practiceQuestionNavClasses(s, q, index);
      grid.children[index].className = cls;
      if (strip) strip.children[index].className = cls;
    });
    return;
  }

  grid.innerHTML = "";
  if (strip) strip.innerHTML = "";
  s.questions.forEach((q, index) => {
    [grid, strip].forEach((container) => {
      if (!container) return;
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = practiceQuestionNavClasses(s, q, index);
      btn.textContent = String(index + 1);
      btn.setAttribute("aria-label", `Question ${index + 1}`);
      btn.addEventListener("click", () => goToPracticeQuestionCard(index));
      container.appendChild(btn);
    });
  });
}

function goToPracticeQuestionCard(index, opts) {
  const s = practiceModeState;
  s.current = index;
  qs("#pm-progress").textContent = `Question ${index + 1} of ${s.questions.length}`;
  const card = qs(`#pm-q-card-${index}`);
  const stream = qs("#pm-question-stream");
  if (card && stream) {
    const streamScrolls = stream.scrollHeight > stream.clientHeight;
    if (streamScrolls) {
      const top = card.offsetTop - stream.offsetTop;
      stream.scrollTo({ top, behavior: "smooth" });
    } else {
      const header = qs("#view-practice-mode .exam-header");
      const strip = qs("#pm-mobile-nav-strip");
      const stickyOffset = (header?.offsetHeight || 0) + (strip?.offsetHeight || 0);
      const cardTop = card.getBoundingClientRect().top + window.scrollY;
      window.scrollTo({ top: cardTop - stickyOffset - 12, behavior: "smooth" });
    }
  }
  updateAllPracticeQuestionCards();
  renderPracticeNavigator();
  scrollPracticeStripToIndex(index);
  if (!(opts && opts.skipSave)) savePracticeProgress();
}

/* Mobile/tablet only: keep #pm-mobile-nav-strip's highlighted number in
   sync with whichever question card is in view, and auto-scroll the strip
   so that number stays visible — same approach as Exam Mode's
   initMobileNavStripSync(), kept as a separate copy since that one reads
   liveExamState/#view-exam specifically. Desktop is unaffected: the strip
   is display:none there via the shared .mobile-nav-strip base rule. */
function scrollPracticeStripToIndex(index) {
  const strip = qs("#pm-mobile-nav-strip");
  const btn = strip?.children[index];
  if (!strip || !btn) return;
  const btnLeft = btn.offsetLeft;
  const btnRight = btnLeft + btn.offsetWidth;
  const viewLeft = strip.scrollLeft;
  const viewRight = viewLeft + strip.clientWidth;
  if (btnLeft < viewLeft || btnRight > viewRight) {
    const target = btnLeft - (strip.clientWidth - btn.offsetWidth) / 2;
    strip.scrollTo({ left: Math.max(0, target), behavior: "smooth" });
  }
}

function initPracticeMobileNavStripSync() {
  const stream = qs("#pm-question-stream");
  const strip = qs("#pm-mobile-nav-strip");
  if (!stream || !strip) return;
  if (practiceModeState && practiceModeState.navSyncObserver) practiceModeState.navSyncObserver.disconnect();

  const mq = window.matchMedia("(max-width: 900px)");
  let observer = null;

  const setup = () => {
    if (observer) { observer.disconnect(); observer = null; }
    if (!mq.matches) return; // desktop: nav strip is hidden, nothing to sync
    const s = practiceModeState;
    if (!s) return;

    const ratios = new Map();
    observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        const index = Number(entry.target.dataset.index);
        ratios.set(index, entry.isIntersecting ? entry.intersectionRatio : 0);
      });
      let bestIndex = s.current, bestRatio = -1;
      ratios.forEach((ratio, index) => {
        if (ratio > bestRatio) { bestRatio = ratio; bestIndex = index; }
      });
      if (bestRatio > 0 && bestIndex !== s.current) {
        s.current = bestIndex;
        qs("#pm-progress").textContent = `Question ${bestIndex + 1} of ${s.questions.length}`;
        renderPracticeNavigator();
        scrollPracticeStripToIndex(bestIndex);
      }
    }, {
      root: null,
      threshold: [0.25, 0.5, 0.75],
      rootMargin: `-${(qs("#view-practice-mode .exam-header")?.offsetHeight || 0) + (strip.offsetHeight || 0)}px 0px -40% 0px`,
    });
    qsa(".question-card", stream).forEach((card) => observer.observe(card));
  };

  mq.addEventListener("change", setup);
  setup();
  if (practiceModeState) {
    practiceModeState.navSyncObserver = { disconnect: () => { if (observer) observer.disconnect(); mq.removeEventListener("change", setup); } };
  }
}

function exitPracticeMode() {
  savePracticeProgress();
  if (practiceModeState && practiceModeState.navSyncObserver) practiceModeState.navSyncObserver.disconnect();
  practiceModeState = null;
  // Use the same history.back()-driven path as every other on-screen
  // Back button (see goBackView's own comment above) instead of a
  // forward-style navigateToView call. navigateToView() pushes a BRAND
  // NEW history entry via showView, which doesn't consume the entry
  // Practice Mode itself pushed on the way in — so viewHistoryStack and
  // the real browser history stack drift apart by one, and the very
  // next Back press (icon or hardware) lands one view off from where
  // the user expects. "practice" is passed only as the goBackView
  // fallback for the rare case this is reached with an empty stack
  // (e.g. a direct/refreshed load straight into Practice Mode).
  goBackView("practice");
}

function initPracticeView() {
  qs("#pm-back-btn")?.addEventListener("click", exitPracticeMode);
}

/* ==========================================================================
   PRACTICE ADMIN PANEL — Subjects + Questions tabs only (no Results/Users,
   per spec: Practice has no schedule or subscriber list). Reuses the exact
   same admin-subject-card / live-admin-exam-row / mcqp-* markup and CSS as
   the Live Exam Admin Panel, but a Subject here is just a name (no course
   start/end date) and a Topic is just a name under a subject (no start
   time, duration, marks, or negative marking) — Practice topics aren't
   scheduled exams. All local-only (practiceState / localStorage): no
   Supabase calls here, per spec, since the database connects later.
   ========================================================================== */

/* ---------- Questions tab: PracticeMCQBuilder ----------
   Second instance of the same createMCQBuilder() factory that powers the
   Live Exam Admin Panel's MCQBuilder above — identical rich-text editor,
   layout picker, AI Mode (with attachments), and PUSH button, just pointed
   at practiceState.subjects[].topics[].questions instead of
   centralExamState.questionBank, and using the "pa-mcqp-" id prefix so it
   can coexist in the DOM with the Live Exam builder without id clashes. */
const PracticeMCQBuilder = createMCQBuilder({
  idPrefix: "pa-mcqp",
  selectFirstMessage: "Select or create a Topic first.",
  getItems() {
    const items = [];
    getPracticeAdminSubjects().forEach((s) => {
      s.topics.forEach((t) => {
        items.push({ id: practiceProgressKey(s.id, t.id), label: `${s.name} - ${t.name}`, groupId: s.id, groupLabel: s.name, topicLabel: t.name });
      });
    });
    return items;
  },
  getItemMeta(itemId) {
    const [subjectId, topicId] = itemId.split("::");
    const found = findPracticeTopic(subjectId, topicId);
    if (!found) return null;
    return { subject: found.subject.name, topic: found.topic.name, language: found.topic.language || "en" };
  },
  getSubtopic() {
    const el = document.getElementById("pa-mcqp-subtopic");
    return el ? el.value : "";
  },
  async getBank(itemId) {
    const [subjectId, topicId] = itemId.split("::");
    const found = findPracticeTopic(subjectId, topicId);
    if (!found) return [];
    // Always force a fresh fetch here rather than serving a stale cache
    // hit: this is the admin editor loading a topic to edit, so it needs
    // the true current state in Storage — not a count-badge estimate from
    // somewhere else in the UI.
    return getPracticeTopicQuestions(subjectId, topicId, { forceRefresh: true });
  },
  async pushQuestions(itemId, converted, lang) {
    const [subjectId, topicId] = itemId.split("::");
    const found = findPracticeTopic(subjectId, topicId);
    if (!found) return;
    // Keep the topic's stored language in sync with whichever EN/বাংলা
    // toggle was active in this builder when the questions were written
    // — same rule as Live Exam's MCQBuilder: only overwrite if the topic
    // is still on the default "en", so an explicit prior choice sticks.
    if (!found.topic.language || found.topic.language === "en") {
      found.topic.language = lang;
      savePracticeState();
    }
    // Throws on failure (network, auth) — pushIntoLive's try/catch is
    // what turns that into a "couldn't save" toast instead of a false
    // success. practiceState itself no longer stores the questions, so
    // there's nothing local to roll back if this fails.
    await pushPracticeTopicQuestions(subjectId, topicId, converted, found.topic.language);
    setPracticeTopicQuestionsCache(subjectId, topicId, converted);
    renderPracticeAdminSubjectList();
  },
  pushedToast(count) {
    return `${count} question${count === 1 ? "" : "s"} pushed into Practice.`;
  },
});

function renderPracticeAdminQuestionBank(preferredItemId) {
  PracticeMCQBuilder.render(preferredItemId);
}

/* ---------- Subjects tab: subject list + subject/topic forms ---------- */
/* ---------- Practice Admin: Subjects tab UI state ----------
   Tracks which subject accordion is open and which inline form (if any)
   is active, so edits render right where the user clicked instead of in
   a shared form fixed at the bottom of the page. Only one of
   editingSubjectId / newSubjectOpen / editingTopic / newTopicForSubject
   is ever set at a time. */
let pracAdminUI = {
  openSubjectId: null,
  editingSubjectId: null,
  newSubjectOpen: false,
  editingTopic: null, // { subjectId, topicId }
  newTopicForSubject: null,
};

registerGlobalDropdown("practice-admin-accordion", () => {
  if (pracAdminUI.openSubjectId === null && !pracAdminUI.editingSubjectId && !pracAdminUI.newSubjectOpen && !pracAdminUI.editingTopic && !pracAdminUI.newTopicForSubject) return;
  pracAdminUI = { openSubjectId: null, editingSubjectId: null, newSubjectOpen: false, editingTopic: null, newTopicForSubject: null };
  renderPracticeAdminSubjectList();
});

/* ---------- Exam Categories tab: category list + category form ----------
   Same inline-form UI pattern as the Subjects tab below (one state object,
   forms render inside the card that's being edited/created), scoped to
   practiceState.categories instead of a single category's subjects[]. */
let pracAdminCategoryUI = {
  editingCategoryId: null,
  newCategoryOpen: false,
};

/** Reads an image File and resolves a full data: URI (unlike
    fileToBase64() above, which strips the prefix for Gemini's inline-data
    API) — this is what gets stored directly in category.icon and dropped
    straight into an <img src>. */
function imageFileToDataUrl(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result || ""));
    reader.onerror = () => reject(reader.error || new Error("FILE_READ_ERROR"));
    reader.readAsDataURL(file);
  });
}
// Holds the icon for whichever category form (new or edit) is currently
// open, since a data: URI is too long to round-trip through a plain
// text input's value attribute on every re-render — the preview below
// the upload button reads from here instead.
let pracAdminCategoryIconDraft = null;
function practiceAdminCategoryIconPreviewHtml(icon) {
  if (!icon) return `<div class="pa-category-icon-preview pa-category-icon-preview--empty">📚</div>`;
  return icon.startsWith("data:image")
    ? `<img class="pa-category-icon-preview" src="${escapeHtml(icon)}" alt="" />`
    : `<div class="pa-category-icon-preview">${escapeHtml(icon)}</div>`;
}
function practiceAdminCategoryFormHtml(category) {
  const icon = pracAdminCategoryIconDraft !== null ? pracAdminCategoryIconDraft : (category ? category.icon || "" : "");
  return `
    <div class="card" style="margin: 0 0 var(--space-4);" data-pa-inline-category-form>
      <div class="card__header">
        <h3 class="text-h4">${category ? "Edit category" : "New category"}</h3>
        <button type="button" class="icon-btn" data-pa-admin-category-form-close aria-label="Close">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"/></svg>
        </button>
      </div>

      <div class="pa-category-icon-row">
        ${practiceAdminCategoryIconPreviewHtml(icon)}
        <div class="pa-category-icon-row__actions">
          <button type="button" class="btn btn-outline btn-sm" data-pa-admin-category-icon-upload>Upload icon</button>
          ${icon ? `<button type="button" class="btn btn-outline btn-sm" data-pa-admin-category-icon-clear>Remove</button>` : ""}
          <input type="file" class="visually-hidden" id="pa-admin-category-icon-input" accept="image/*" aria-hidden="true" tabindex="-1" />
        </div>
      </div>

      <div>
        <label class="form-label" for="pa-admin-category-name">Category name</label>
        <input type="text" class="form-control" id="pa-admin-category-name" placeholder="e.g. ব্যাংক প্রিলিমিনারী" value="${category ? escapeHtml(category.name) : ""}" />
      </div>
      <div style="margin-top: var(--space-3);">
        <label class="form-label" for="pa-admin-category-desc">Category details</label>
        <textarea class="form-control" id="pa-admin-category-desc" rows="3" placeholder="A short description of this exam category">${category ? escapeHtml(category.description || "") : ""}</textarea>
      </div>

      <div class="pa-inline-form-row__actions" style="margin-top: var(--space-3);">
        <button type="button" class="btn btn-primary" data-pa-admin-category-save="${category ? escapeHtml(category.id) : ""}">Save Category</button>
        <button type="button" class="btn btn-secondary" data-pa-admin-category-form-close>Cancel</button>
      </div>
    </div>`;
}

function renderPracticeAdminCategoryList() {
  const container = qs("#pa-admin-category-list");
  if (!container) return;

  const categories = practiceState.categories || [];
  const newCategoryFormHtml = pracAdminCategoryUI.newCategoryOpen ? practiceAdminCategoryFormHtml(null) : "";

  if (!categories.length) {
    container.innerHTML = newCategoryFormHtml || `<div class="card text-center text-secondary" style="padding: var(--space-8);">No exam categories yet - click "New Category" to add one (e.g. "ব্যাংক প্রিলিমিনারী"). It'll show up as a card on the Practice page.</div>`;
    wirePracticeAdminCategoryList(container);
    return;
  }

  container.innerHTML = newCategoryFormHtml + categories.map((cat) => {
    const isEditingThisCategory = pracAdminCategoryUI.editingCategoryId === cat.id;
    const subjectCount = (cat.subjects || []).length;
    const iconHtml = cat.icon && cat.icon.startsWith("data:image")
      ? `<img class="pa-category-icon-preview pa-category-icon-preview--sm" src="${escapeHtml(cat.icon)}" alt="" />`
      : `<span style="font-size: 1.4rem; line-height: 1;">${escapeHtml(cat.icon || "📚")}</span>`;
    return `
    <section class="pp-subject is-open" data-category-card="${escapeHtml(cat.id)}">
      <div class="pp-subject__head" style="cursor: default;">
        <div class="pp-subject__title-wrap" style="display:flex; align-items:center; gap: var(--space-2);">
          ${iconHtml}
          <div>
            <div class="pp-subject__title">${escapeHtml(cat.name)}</div>
            ${cat.description ? `<div class="text-muted" style="font-size: var(--font-size-caption); margin-top: 2px;">${escapeHtml(cat.description)}</div>` : ""}
          </div>
        </div>
        <span class="text-muted" style="font-size: var(--font-size-caption); flex-shrink:0;">${subjectCount} subject${subjectCount === 1 ? "" : "s"}</span>
      </div>
      <div class="pp-subject__topics">
        <div class="pp-subject__topics-inner">
          ${isEditingThisCategory ? practiceAdminCategoryFormHtml(cat) : ""}
          <div class="admin-subject-card__actions" style="margin-top: ${isEditingThisCategory ? "0" : "var(--space-1)"};">
            <button type="button" class="btn btn-outline btn-sm" data-pa-admin-edit-category="${escapeHtml(cat.id)}">Edit</button>
            <button type="button" class="btn btn-outline btn-sm" data-pa-admin-delete-category="${escapeHtml(cat.id)}">Delete</button>
          </div>
        </div>
      </div>
    </section>`;
  }).join("");

  wirePracticeAdminCategoryList(container);
}

function wirePracticeAdminCategoryList(container) {
  qsa("[data-pa-admin-edit-category]", container).forEach((btn) => {
    btn.addEventListener("click", () => {
      const id = btn.getAttribute("data-pa-admin-edit-category");
      pracAdminCategoryIconDraft = null; // form reads straight from the category being edited
      pracAdminCategoryUI = { editingCategoryId: id, newCategoryOpen: false };
      renderPracticeAdminCategoryList();
    });
  });

  qsa("[data-pa-admin-delete-category]", container).forEach((btn) => {
    btn.addEventListener("click", async () => {
      const id = btn.getAttribute("data-pa-admin-delete-category");
      const category = (practiceState.categories || []).find((c) => c.id === id);
      if (!category) return;
      if (practiceState.categories.length <= 1) { showToast("At least one exam category is required.", "danger"); return; }
      const subjectCount = (category.subjects || []).length;
      const msg = subjectCount
        ? `"${category.name}" has ${subjectCount} subject(s) under it. Deleting the category also deletes all of its subjects, topics and questions. Continue?`
        : `Delete the category "${category.name}"?`;
      if (!confirm(msg)) return;

      practiceState.categories = practiceState.categories.filter((c) => c.id !== id);
      // If the deleted category was the active one (e.g. shown on the
      // Subjects tab / Statistics page), fall back to whatever is first
      // now so nothing is left pointing at a category that no longer
      // exists.
      if (activePracticeCategoryId === id) activePracticeCategoryId = (practiceState.categories[0] || {}).id || null;
      savePracticeState();
      renderPracticeAdminCategoryList();
      renderPracticeAdminCategorySelect();
      renderPracticeAdminSubjectList();
      showToast("Category deleted.", "success");
      // Sync the tree to the server so students' browsers stop listing
      // this category too — same reasoning as the Subjects tab's
      // delete handlers (see syncPracticeManifestAfterEdit above them).
      try {
        await syncPracticeManifestAfterEdit();
      } catch (e) {
        console.error("Could not sync category list to server:", e);
        showToast("Category deleted locally, but the change may not have reached students yet.", "danger");
      }
    });
  });

  qsa("[data-pa-admin-category-form-close]", container).forEach((btn) => {
    btn.addEventListener("click", () => {
      pracAdminCategoryIconDraft = null;
      pracAdminCategoryUI = { editingCategoryId: null, newCategoryOpen: false };
      renderPracticeAdminCategoryList();
    });
  });

  // Icon upload: clicking the visible button forwards to the hidden
  // file input; picking a file reads it into pracAdminCategoryIconDraft
  // (a data: URI) and re-renders just the form so the preview updates.
  qs("[data-pa-admin-category-icon-upload]", container)?.addEventListener("click", () => {
    qs("#pa-admin-category-icon-input")?.click();
  });
  qs("#pa-admin-category-icon-input", container)?.addEventListener("change", async (e) => {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    if (!file.type.startsWith("image/")) { showToast("Please choose an image file.", "danger"); return; }
    try {
      pracAdminCategoryIconDraft = await imageFileToDataUrl(file);
      renderPracticeAdminCategoryList();
    } catch (err) {
      console.error(err);
      showToast("Couldn't read that image.", "danger");
    }
  });
  qs("[data-pa-admin-category-icon-clear]", container)?.addEventListener("click", () => {
    pracAdminCategoryIconDraft = "";
    renderPracticeAdminCategoryList();
  });

  qsa("[data-pa-admin-category-save]", container).forEach((btn) => {
    btn.addEventListener("click", async () => {
      const editingId = btn.getAttribute("data-pa-admin-category-save");
      const name = qs("#pa-admin-category-name").value.trim();
      const description = qs("#pa-admin-category-desc").value.trim();
      // The icon lives in pracAdminCategoryIconDraft once the admin has
      // touched the upload/remove controls (see wiring above); otherwise
      // fall back to whatever the category already had (edit) or none
      // (new category, before any upload).
      const icon = pracAdminCategoryIconDraft !== null ? pracAdminCategoryIconDraft : "";
      if (!name) { showToast("Category name is required.", "danger"); return; }
      const categories = practiceState.categories || (practiceState.categories = []);
      const duplicate = categories.some((c) => c.name.toLowerCase() === name.toLowerCase() && c.id !== editingId);
      if (duplicate) { showToast("A category with that name already exists.", "danger"); return; }

      if (editingId) {
        const category = categories.find((c) => c.id === editingId);
        if (category) {
          category.name = name;
          category.description = description;
          if (pracAdminCategoryIconDraft !== null) category.icon = icon;
        }
      } else {
        const newCategory = { id: practiceCategoryId(), name, description, icon: icon || "📚", subjects: [] };
        categories.push(newCategory);
        // New category becomes the active one so the admin lands
        // straight on its (empty) Subjects list to start adding
        // subjects/topics right away.
        activePracticeCategoryId = newCategory.id;
      }
      savePracticeState();
      pracAdminCategoryIconDraft = null;
      pracAdminCategoryUI = { editingCategoryId: null, newCategoryOpen: false };
      renderPracticeAdminCategoryList();
      renderPracticeAdminCategorySelect();
      renderPracticeAdminSubjectList();
      showToast("Category saved.", "success");
      // Same sync-after-edit pattern as the Subjects tab — an
      // added/renamed/re-iconed category needs to reach other devices,
      // not just sit in this admin's localStorage.
      try {
        await syncPracticeManifestAfterEdit();
      } catch (e) {
        console.error("Could not sync category list to server:", e);
        showToast("Category saved locally, but the change may not have reached students yet.", "danger");
      }
    });
  });
}

/** Category picker shown above the Subjects tab's subject list — lets the
    admin choose which category's Subject/Topic tree getPracticeAdminSubjects()
    reads/writes (activePracticeCategoryId), same category set the Practice
    Panel and Statistics page use. Hidden entirely when there's only one
    category, same threshold as renderStatsCategoryTabs(). */
function renderPracticeAdminCategorySelect() {
  const wrap = qs("#pa-admin-category-select")?.closest(".form-group");
  const select = qs("#pa-admin-category-select");
  if (!select) return;
  const categories = practiceState.categories || [];
  if (wrap) wrap.hidden = categories.length < 2;
  select.innerHTML = categories.map((c) => {
    const iconText = c.icon && !c.icon.startsWith("data:image") ? c.icon : "";
    return `<option value="${escapeHtml(c.id)}" ${c.id === activePracticeCategoryId ? "selected" : ""}>${escapeHtml(iconText)} ${escapeHtml(c.name)}</option>`;
  }).join("");
}

function practiceAdminSubjectFormHtml(subject) {
  return `
    <div class="card" style="margin: 0 0 var(--space-4);" data-pa-inline-subject-form>
      <div class="card__header">
        <h3 class="text-h4">${subject ? "Edit subject" : "New subject"}</h3>
        <button type="button" class="icon-btn" data-pa-admin-subject-form-close aria-label="Close">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"/></svg>
        </button>
      </div>
      <div class="pa-inline-form-row">
        <div class="pa-inline-form-row__field">
          <label class="form-label" for="pa-admin-subject-name">Subject name</label>
          <input type="text" class="form-control" id="pa-admin-subject-name" placeholder="e.g. English Grammar" value="${subject ? escapeHtml(subject.name) : ""}" />
        </div>
        <div class="pa-inline-form-row__actions">
          <button type="button" class="btn btn-primary" data-pa-admin-subject-save="${subject ? escapeHtml(subject.id) : ""}">Save Subject</button>
          <button type="button" class="btn btn-secondary" data-pa-admin-subject-form-close>Cancel</button>
        </div>
      </div>
    </div>`;
}

function practiceAdminTopicFormHtml(subject, topic) {
  return `
    <div class="card" style="margin: var(--space-3) 0 0;" data-pa-inline-topic-form>
      <div class="card__header">
        <h3 class="text-h4">${topic ? "Edit Topic" : "New Topic"}</h3>
        <button type="button" class="icon-btn" data-pa-admin-topic-form-close aria-label="Close">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"/></svg>
        </button>
      </div>
      <div class="config-grid">
        <div>
          <label class="form-label" for="pa-admin-topic-subject">Subject</label>
          <select class="form-control" id="pa-admin-topic-subject">
            ${getPracticeAdminSubjects().map((s) => `<option value="${escapeHtml(s.id)}" ${s.id === subject.id ? "selected" : ""}>${escapeHtml(s.name)}</option>`).join("")}
          </select>
        </div>
        <div>
          <label class="form-label" for="pa-admin-topic-main">Main topic</label>
          <select class="form-control" id="pa-admin-topic-main">
            <option value="">— No main topic —</option>
            ${(subject.mainTopics || []).map((m) => `<option value="${escapeHtml(m.id)}" ${topic && topic.mainTopicId === m.id ? "selected" : ""}>${escapeHtml(m.name)}</option>`).join("")}
          </select>
        </div>
        <div>
          <label class="form-label" for="pa-admin-topic-name">Topic name</label>
          <input type="text" class="form-control" id="pa-admin-topic-name" placeholder="e.g. Noun, Tense, Subject-Verb Agreement" value="${topic ? escapeHtml(topic.name) : ""}" />
        </div>
      </div>
      <div class="pa-topic-form-actions">
        <button type="button" class="btn btn-primary btn-sm" data-pa-admin-topic-save="${escapeHtml(subject.id)}::${topic ? escapeHtml(topic.id) : ""}">Save Topic</button>
        <button type="button" class="btn btn-secondary btn-sm" data-pa-admin-topic-form-close>Cancel</button>
        <button type="button" class="btn btn-outline btn-sm" data-pa-admin-tab-jump="questions">Add Question</button>
      </div>
    </div>`;
}

function renderPracticeAdminSubjectList() {
  const container = qs("#pa-admin-subject-list");
  if (!container) return;

  const newSubjectFormHtml = pracAdminUI.newSubjectOpen ? practiceAdminSubjectFormHtml(null) : "";

  if (!getPracticeAdminSubjects().length) {
    container.innerHTML = newSubjectFormHtml || `<div class="card text-center text-secondary" style="padding: var(--space-8);">No subjects yet - click "New Subject" to start (e.g. "English Grammar"), then add Topics under it.</div>`;
    wirePracticeAdminSubjectList(container);
    return;
  }

  container.innerHTML = newSubjectFormHtml + getPracticeAdminSubjects().map((subject) => {
    const isOpen = pracAdminUI.openSubjectId === subject.id;
    const isEditingThisSubject = pracAdminUI.editingSubjectId === subject.id;

    const renderAdminTopicRow = (topic) => {
      const cached = practiceQuestionCache.get(`${subject.id}::${topic.id}`);
      const qCountLabel = cached ? `${cached.length} question${cached.length === 1 ? "" : "s"}` : "…";
      const isEditingThisTopic = pracAdminUI.editingTopic && pracAdminUI.editingTopic.subjectId === subject.id && pracAdminUI.editingTopic.topicId === topic.id;
      return `
          <div class="live-admin-exam-row">
            <div class="live-admin-exam-row__body">
              <div class="live-admin-exam-row__title">${escapeHtml(topic.name || "Untitled topic")}</div>
              <div class="live-admin-exam-row__meta" data-pa-qcount="${escapeHtml(subject.id)}::${escapeHtml(topic.id)}">${qCountLabel}</div>
            </div>
            <div class="live-admin-exam-row__actions">
              <button type="button" class="btn btn-outline btn-sm" data-pa-admin-edit-topic="${escapeHtml(subject.id)}::${escapeHtml(topic.id)}">Edit</button>
              <button type="button" class="btn btn-outline btn-sm" data-pa-admin-delete-topic="${escapeHtml(subject.id)}::${escapeHtml(topic.id)}">Delete</button>
            </div>
          </div>
          ${isEditingThisTopic ? practiceAdminTopicFormHtml(subject, topic) : ""}`;
    };
    const mainTopics = subject.mainTopics || [];
    const groupsHtml = mainTopics.map((main) => {
      const inGroup = subject.topics.filter((t) => t.mainTopicId === main.id);
      return `
        <div class="pa-main-group">
          <div class="pa-main-group__head">
            <span class="pa-main-group__name">${escapeHtml(main.name)}</span>
            <button type="button" class="btn btn-outline btn-sm" data-pa-admin-delete-main="${escapeHtml(subject.id)}::${escapeHtml(main.id)}">Delete</button>
          </div>
          ${inGroup.length ? inGroup.map(renderAdminTopicRow).join("") : `<div class="pp-subject__empty">No topics under "${escapeHtml(main.name)}" yet.</div>`}
        </div>`;
    }).join("");
    const ungrouped = subject.topics.filter((t) => !mainTopics.some((m) => m.id === t.mainTopicId));
    const ungroupedHtml = ungrouped.length
      ? (mainTopics.length ? `<div class="pa-main-group__name" style="margin: var(--space-3) 0 var(--space-2);">Without main topic</div>` : "") + ungrouped.map(renderAdminTopicRow).join("")
      : "";
    const topicRows = (groupsHtml + ungroupedHtml) || `<div class="pp-subject__empty">No Topics yet under "${escapeHtml(subject.name)}" - add one like Noun or Tense.</div>`;

    const newTopicFormHtml = pracAdminUI.newTopicForSubject === subject.id ? practiceAdminTopicFormHtml(subject, null) : "";
    const newMainFormHtml = pracAdminUI.newMainForSubject === subject.id ? `
      <div class="card pa-main-form">
        <div class="pa-main-form__field">
          <label class="form-label" for="pa-admin-main-name">Main topic name</label>
          <input type="text" class="form-control" id="pa-admin-main-name" placeholder="e.g. প্রাচীন যুগ" />
        </div>
        <div class="pa-main-form__actions">
          <button type="button" class="btn btn-primary btn-sm" data-pa-admin-main-save="${escapeHtml(subject.id)}">Save Main Topic</button>
        </div>
      </div>` : "";

    return `
    <section class="pp-subject${isOpen ? " is-open" : ""}" data-subject-card="${escapeHtml(subject.id)}">
      <div class="pp-subject__head" style="cursor: default;">
        <button type="button" class="pp-subject__title-wrap" data-subject-toggle="${escapeHtml(subject.id)}" style="display:flex; align-items:center; gap: var(--space-3); flex: 1; min-width: 0; background: none; border: none; padding: 0; text-align: left; cursor: pointer;">
          <div class="pp-subject__title">${escapeHtml(subject.name)}</div>
          <svg class="pp-subject__chevron" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M6 9l6 6 6-6"/></svg>
        </button>
        <div class="admin-subject-card__actions" style="flex-shrink: 0;">
          <button type="button" class="btn btn-outline btn-sm" data-pa-admin-edit-subject="${escapeHtml(subject.id)}">Edit</button>
          <button type="button" class="btn btn-outline btn-sm" data-pa-admin-delete-subject="${escapeHtml(subject.id)}">Delete</button>
        </div>
      </div>
      <div class="pp-subject__topics">
        <div class="pp-subject__topics-inner">
          ${isEditingThisSubject ? practiceAdminSubjectFormHtml(subject) : ""}
          ${topicRows}
          ${newMainFormHtml}
          ${newTopicFormHtml}
          <div class="admin-subject-card__actions" style="margin-top: var(--space-3);">
            <button type="button" class="btn btn-primary btn-sm" data-pa-admin-new-topic-for="${escapeHtml(subject.id)}">
              <svg viewBox="0 0 24 24" fill="none" aria-hidden="true" width="16" height="16"><path d="M12 5v14M5 12h14" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>
              New Topic
            </button>
            <button type="button" class="btn btn-outline btn-sm" data-pa-admin-new-main="${escapeHtml(subject.id)}" style="margin-left: var(--space-2);">
              New Main Topic
            </button>
          </div>
        </div>
      </div>
    </section>`;
  }).join("");

  wirePracticeAdminSubjectList(container);
  patchPracticeAdminQuestionCounts(container);
}

/** Fetches each visible topic's real question count from Storage (or the
    session cache) and patches it into the "N questions" label after the
    initial render, since that data no longer lives on the local topic
    object. Each fetch is independent — one slow/failed topic just leaves
    its own label as "…" rather than blocking the others. */
function patchPracticeAdminQuestionCounts(container) {
  if (!container) return;
  qsa("[data-pa-qcount]", container).forEach(async (el) => {
    const [subjectId, topicId] = el.getAttribute("data-pa-qcount").split("::");
    try {
      const questions = await getPracticeTopicQuestions(subjectId, topicId);
      el.textContent = `${questions.length} question${questions.length === 1 ? "" : "s"}`;
    } catch (e) {
      console.error(e);
      el.textContent = "couldn't load count";
    }
  });
}

function wirePracticeAdminSubjectList(container) {
  qsa("[data-pa-admin-new-main]", container).forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.stopPropagation();
      const subjectId = btn.getAttribute("data-pa-admin-new-main");
      pracAdminUI = { openSubjectId: subjectId, editingSubjectId: null, newSubjectOpen: false, editingTopic: null, newTopicForSubject: null, newMainForSubject: subjectId };
      renderPracticeAdminSubjectList();
    });
  });
  qsa("[data-pa-admin-main-save]", container).forEach((btn) => {
    btn.addEventListener("click", async (e) => {
      e.stopPropagation();
      const subjectId = btn.getAttribute("data-pa-admin-main-save");
      const name = qs("#pa-admin-main-name").value.trim();
      if (!name) { showToast("Main topic name is required.", "danger"); return; }
      const subject = getPracticeAdminSubjects().find((s) => s.id === subjectId);
      if (!subject) return;
      subject.mainTopics = [...(subject.mainTopics || []), { id: practiceTopicId(), name }];
      pracAdminUI.newMainForSubject = null;
      pracAdminUI.openSubjectId = subjectId;
      savePracticeState();
      renderPracticeAdminSubjectList();
      await syncPracticeManifestAfterEdit();
    });
  });
  qsa("[data-pa-admin-delete-main]", container).forEach((btn) => {
    btn.addEventListener("click", async (e) => {
      e.stopPropagation();
      const [subjectId, mainId] = btn.getAttribute("data-pa-admin-delete-main").split("::");
      const subject = getPracticeAdminSubjects().find((s) => s.id === subjectId);
      if (!subject) return;
      const main = (subject.mainTopics || []).find((m) => m.id === mainId);
      if (!main) return;
      if (!confirm(`Delete the main topic "${main.name}"? Its topics stay, but move to "Without main topic".`)) return;
      subject.mainTopics = subject.mainTopics.filter((m) => m.id !== mainId);
      subject.topics.forEach((t) => { if (t.mainTopicId === mainId) t.mainTopicId = null; });
      savePracticeState();
      renderPracticeAdminSubjectList();
      await syncPracticeManifestAfterEdit();
    });
  });
  qsa("#pa-admin-topic-subject", container).forEach((sel) => {
    sel.addEventListener("change", () => {
      const subject = getPracticeAdminSubjects().find((s) => s.id === sel.value);
      const mainSel = qs("#pa-admin-topic-main");
      if (!mainSel) return;
      mainSel.innerHTML = `<option value="">— No main topic —</option>` +
        ((subject && subject.mainTopics) || []).map((m) => `<option value="${escapeHtml(m.id)}">${escapeHtml(m.name)}</option>`).join("");
    });
  });
  qsa("[data-subject-toggle]", container).forEach((btn) => {
    btn.addEventListener("click", () => {
      const id = btn.getAttribute("data-subject-toggle");
      const willOpen = pracAdminUI.openSubjectId !== id;
      if (willOpen) closeOtherGlobalDropdowns("practice-admin-accordion");
      pracAdminUI.openSubjectId = willOpen ? id : null;
      renderPracticeAdminSubjectList();
    });
  });
  qsa("[data-pa-admin-new-topic-for]", container).forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.stopPropagation();
      const subjectId = btn.getAttribute("data-pa-admin-new-topic-for");
      closeOtherGlobalDropdowns("practice-admin-accordion");
      pracAdminUI = { openSubjectId: subjectId, editingSubjectId: null, newSubjectOpen: false, editingTopic: null, newTopicForSubject: subjectId };
      renderPracticeAdminSubjectList();
    });
  });
  qsa("[data-pa-admin-edit-topic]", container).forEach((btn) => {
    btn.addEventListener("click", () => {
      const [subjectId, topicId] = btn.getAttribute("data-pa-admin-edit-topic").split("::");
      closeOtherGlobalDropdowns("practice-admin-accordion");
      pracAdminUI = { openSubjectId: subjectId, editingSubjectId: null, newSubjectOpen: false, editingTopic: { subjectId, topicId }, newTopicForSubject: null };
      renderPracticeAdminSubjectList();
    });
  });
  qsa("[data-pa-admin-delete-topic]", container).forEach((btn) => {
    btn.addEventListener("click", async () => {
      const [subjectId, topicId] = btn.getAttribute("data-pa-admin-delete-topic").split("::");
      const found = findPracticeTopic(subjectId, topicId);
      if (!found) return;
      if (!confirm(`Delete the topic "${found.topic.name}"? This also removes its question bank. This can't be undone.`)) return;
      found.subject.topics = found.subject.topics.filter((t) => t.id !== topicId);
      savePracticeState();
      clearPracticeTopicQuestionsCache(subjectId, topicId);
      renderPracticeAdminSubjectList();
      renderPracticeAdminQuestionBank();
      showToast("Topic deleted.", "success");
      // Sync the tree itself first — students' browsers need to stop
      // listing this topic before it matters whether its question-bank
      // file also gets cleaned up. Both are best-effort from here: the
      // topic is already gone from this admin's local view regardless
      // (practiceState no longer references it), so a failure in either
      // just means stale server-side data rather than the delete
      // appearing to fail to the admin.
      try {
        await syncPracticeManifestAfterEdit();
      } catch (e) {
        console.error("Could not sync subject/topic list to server:", e);
        showToast("Topic deleted locally, but the change may not have reached students yet.", "danger");
      }
      try {
        await deletePracticeTopicQuestions(subjectId, topicId);
      } catch (e) {
        console.error("Could not delete topic's question bank from Storage:", e);
      }
    });
  });
  qsa("[data-pa-admin-edit-subject]", container).forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.stopPropagation();
      const id = btn.getAttribute("data-pa-admin-edit-subject");
      closeOtherGlobalDropdowns("practice-admin-accordion");
      pracAdminUI = { openSubjectId: id, editingSubjectId: id, newSubjectOpen: false, editingTopic: null, newTopicForSubject: null };
      renderPracticeAdminSubjectList();
    });
  });
  qsa("[data-pa-admin-delete-subject]", container).forEach((btn) => {
    btn.addEventListener("click", async (e) => {
      e.stopPropagation();
      const id = btn.getAttribute("data-pa-admin-delete-subject");
      const subject = getPracticeAdminSubjects().find((s) => s.id === id);
      if (!subject) return;
      if (subject.topics.length && !confirm(`"${subject.name}" has ${subject.topics.length} Topic(s) under it. Deleting the subject also deletes all of them and their questions. Continue?`)) return;
      if (!subject.topics.length && !confirm(`Delete the subject "${subject.name}"?`)) return;
      const topicIds = subject.topics.map((t) => t.id);
      setPracticeAdminSubjects(getPracticeAdminSubjects().filter((s) => s.id !== id));
      savePracticeState();
      topicIds.forEach((topicId) => clearPracticeTopicQuestionsCache(id, topicId));
      renderPracticeAdminSubjectList();
      renderPracticeAdminQuestionBank();
      showToast("Subject and its topics deleted.", "success");
      // Sync the tree first (same reasoning as the topic-delete handler
      // above), then best-effort cleanup in Storage — one failed file shouldn't
      // block or roll back the rest.
      try {
        await syncPracticeManifestAfterEdit();
      } catch (e) {
        console.error("Could not sync subject/topic list to server:", e);
        showToast("Subject deleted locally, but the change may not have reached students yet.", "danger");
      }
      const results = await Promise.allSettled(topicIds.map((topicId) => deletePracticeTopicQuestions(id, topicId)));
      results.forEach((r, i) => {
        if (r.status === "rejected") console.error(`Could not delete question bank for topic ${topicIds[i]}:`, r.reason);
      });
    });
  });

  // Inline subject form (New or Edit — practiceAdminSubjectFormHtml)
  qsa("[data-pa-admin-subject-form-close]", container).forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.stopPropagation();
      pracAdminUI.editingSubjectId = null;
      pracAdminUI.newSubjectOpen = false;
      renderPracticeAdminSubjectList();
    });
  });
  qsa("[data-pa-admin-subject-save]", container).forEach((btn) => {
    btn.addEventListener("click", async (e) => {
      e.stopPropagation();
      const editingId = btn.getAttribute("data-pa-admin-subject-save");
      const name = qs("#pa-admin-subject-name").value.trim();
      if (!name) { showToast("Subject name is required.", "danger"); return; }
      const duplicate = getPracticeAdminSubjects().some((s) => s.name.toLowerCase() === name.toLowerCase() && s.id !== editingId);
      if (duplicate) { showToast("A subject with that name already exists.", "danger"); return; }

      if (editingId) {
        const subject = getPracticeAdminSubjects().find((s) => s.id === editingId);
        if (subject) subject.name = name;
      } else {
        getPracticeAdminSubjects().push({ id: practiceSubjectId(), name, topics: [] });
      }
      savePracticeState();
      pracAdminUI.editingSubjectId = null;
      pracAdminUI.newSubjectOpen = false;
      renderPracticeAdminSubjectList();
      // Sync to the Worker so every student's browser picks up the new/
      // renamed subject — without this, the subject only ever exists in
      // this admin's own localStorage (the original bug this whole sync
      // layer fixes).
      try {
        await syncPracticeManifestAfterEdit();
        showToast("Subject saved.", "success");
      } catch (err) {
        console.error("Could not sync subject/topic list to server:", err);
        showToast("Subject saved locally, but the change may not have reached students yet.", "danger");
      }
    });
  });

  // Inline topic form (New or Edit — practiceAdminTopicFormHtml)
  qsa("[data-pa-admin-topic-form-close]", container).forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.stopPropagation();
      pracAdminUI.editingTopic = null;
      pracAdminUI.newTopicForSubject = null;
      renderPracticeAdminSubjectList();
    });
  });
  qsa("[data-pa-admin-topic-save]", container).forEach((btn) => {
    btn.addEventListener("click", async (e) => {
      e.stopPropagation();
      const [editingSubjectId, editingTopicId] = btn.getAttribute("data-pa-admin-topic-save").split("::");
      const subjectId = qs("#pa-admin-topic-subject").value;
      const name = qs("#pa-admin-topic-name").value.trim();
      if (!subjectId) { showToast("Add a Subject first, then pick it here.", "danger"); return; }
      if (!name) { showToast("Topic name is required - e.g. Noun, Tense.", "danger"); return; }
      const subject = getPracticeAdminSubjects().find((s) => s.id === subjectId);
      if (!subject) { showToast("Subject not found.", "danger"); return; }

      let savedTopicId = editingTopicId;
      let movedFromSubjectId = null; // set only when the topic's Storage file needs to move
      if (editingTopicId && editingSubjectId === subjectId) {
        const topic = subject.topics.find((t) => t.id === editingTopicId);
        if (topic) topic.name = name;
      } else if (editingTopicId && editingSubjectId !== subjectId) {
        // Moved to a different subject. The topic keeps its own id, but
        // Storage's key is topics/{subjectId}/{topicId}.json — keyed on
        // *both* ids — so its question bank file has to move from the
        // old subject's path to the new one, not just the local metadata.
        const oldSubject = getPracticeAdminSubjects().find((s) => s.id === editingSubjectId);
        const topic = oldSubject ? oldSubject.topics.find((t) => t.id === editingTopicId) : null;
        if (topic) {
          oldSubject.topics = oldSubject.topics.filter((t) => t.id !== editingTopicId);
          topic.name = name;
          subject.topics.push(topic);
          movedFromSubjectId = editingSubjectId;
        }
      } else {
        savedTopicId = practiceTopicId();
        subject.topics.push({ id: savedTopicId, name, questions: [], language: "en" });
      }
      const mainSel = qs("#pa-admin-topic-main");
      const savedTopic = subject.topics.find((t) => t.id === savedTopicId);
      if (savedTopic) savedTopic.mainTopicId = mainSel && mainSel.value ? mainSel.value : null;
      savePracticeState();
      pracAdminUI.editingTopic = null;
      pracAdminUI.newTopicForSubject = null;
      pracAdminUI.openSubjectId = subjectId;
      renderPracticeAdminSubjectList();

      // Sync the tree itself before touching Storage question content below —
      // students need the new/renamed/moved topic id to exist in the
      // manifest before there's any point fetching questions for it.
      let manifestSyncFailed = false;
      try {
        await syncPracticeManifestAfterEdit();
      } catch (err) {
        console.error("Could not sync subject/topic list to server:", err);
        manifestSyncFailed = true;
        showToast("Topic saved locally, but the change may not have reached students yet.", "danger");
      }

      let moveFailed = false;
      if (movedFromSubjectId) {
        // Copy the question bank to its new path, then remove the old
        // one — and do this BEFORE renderPracticeAdminQuestionBank()
        // below. That call triggers the editor's getBank(), which always
        // force-fetches the new subjectId::topicId key (see getBank's
        // own comment) — if the copy hasn't landed in Storage yet, that fetch
        // returns an empty bank and the editor would show "0 questions"
        // for a topic that actually still has its questions, just not
        // copied to the new path yet. Awaiting the move first means the
        // editor's very first render already sees the real content.
        try {
          const questions = await getPracticeTopicQuestions(movedFromSubjectId, editingTopicId, { forceRefresh: true });
          await pushPracticeTopicQuestions(subjectId, editingTopicId, questions);
          setPracticeTopicQuestionsCache(subjectId, editingTopicId, questions);
          await deletePracticeTopicQuestions(movedFromSubjectId, editingTopicId);
          clearPracticeTopicQuestionsCache(movedFromSubjectId, editingTopicId);
        } catch (err) {
          console.error("Could not move topic's question bank in Storage:", err);
          moveFailed = true;
          showToast("Topic moved, but its questions may not have followed - check both subjects.", "danger");
        }
      }

      renderPracticeAdminQuestionBank(`${subjectId}::${savedTopicId}`);
      patchPracticeAdminQuestionCounts(qs("#pa-admin-subject-list"));
      // Skip the generic success toast when the move's own warning toast
      // or the manifest-sync warning toast already fired above — stacking
      // a "...may not have reached students"/"...may not have followed"
      // (danger) toast with "Topic saved." (success) right after it reads
      // as a contradiction, when only one of them is the real outcome the
      // admin needs to act on.
      if (!moveFailed && !manifestSyncFailed) showToast("Topic saved.", "success");
    });
  });

  // "Add Question" button inside an inline Topic form jumps to the
  // Questions tab, same as any other data-pa-admin-tab-jump control —
  // bound here too since this button is (re)rendered dynamically and
  // isn't present at initPracticeAdminPanel's one-time init wiring.
  qsa("[data-pa-admin-tab-jump]", container).forEach((btn) => {
    btn.addEventListener("click", () => activatePracticeAdminTab(btn.getAttribute("data-pa-admin-tab-jump")));
  });
}

function practiceSubjectId() { return "ps" + Date.now().toString(36) + Math.random().toString(36).slice(2, 6); }
function practiceTopicId() { return "pt" + Date.now().toString(36) + Math.random().toString(36).slice(2, 6); }

function renderPracticeAdminPanel() {
  // Real access-control gate (mirrors renderLiveExamAdminPanel() above) —
  // the navigateToView() check is only a convenience fast-path; anyone
  // reaching this function directly (stale hash, browser back/forward,
  // dev tools) must still be blocked here regardless of how they arrived.
  if (!isPracticeAdmin()) {
    showToast("This panel is restricted to the site admin.", "danger");
    showView("practice");
    renderPracticeCategoryList();
    return;
  }
  renderPracticeAdminCategoryList();
  renderPracticeAdminCategorySelect();
  renderPracticeAdminSubjectList();
  renderPracticeAdminQuestionBank();
}

// Tabs: Categories / Subjects / Questions / AGQ. Top level (not nested in
// initPracticeAdminPanel) so both the one-time init wiring and the
// dynamically re-rendered subject list (which can contain an "Add
// Question" tab-jump button inside an inline Topic form) can bind to it.
function activatePracticeAdminTab(target) {
  qsa("[data-pa-admin-tab]").forEach((t) => { t.classList.remove("is-active"); t.setAttribute("aria-selected", "false"); });
  const tabBtn = qs(`[data-pa-admin-tab="${target}"]`);
  if (tabBtn) { tabBtn.classList.add("is-active"); tabBtn.setAttribute("aria-selected", "true"); }
  qsa(".view#view-practice-admin .admin-tab-panel").forEach((p) => (p.style.display = "none"));
  const panel = qs(`#pa-admin-panel-${target}`);
  if (panel) panel.style.display = "";
  // AGQ's own tab bar (নিয়ন্ত্রণ/রিভিউ কিউ/হিস্টোরি) sits directly under
  // this outer Subjects/Questions/AGQ bar with no panel content between
  // them, so the two are visually joined into one grouped control only
  // while AGQ is active — see .pa-tabs--joined in the CSS.
  if (tabBtn) tabBtn.closest(".tabs")?.classList.toggle("pa-tabs--joined", target === "agq");
}

function initPracticeAdminPanel() {
  qsa("[data-pa-admin-tab]").forEach((tabBtn) => {
    tabBtn.addEventListener("click", () => activatePracticeAdminTab(tabBtn.getAttribute("data-pa-admin-tab")));
  });
  qsa("[data-pa-admin-tab-jump]").forEach((btn) => {
    btn.addEventListener("click", () => activatePracticeAdminTab(btn.getAttribute("data-pa-admin-tab-jump")));
  });

  qs("#pa-admin-new-subject-btn")?.addEventListener("click", () => {
    closeOtherGlobalDropdowns("practice-admin-accordion");
    pracAdminUI = { openSubjectId: null, editingSubjectId: null, newSubjectOpen: true, editingTopic: null, newTopicForSubject: null };
    renderPracticeAdminSubjectList();
  });

  qs("#pa-admin-new-category-btn")?.addEventListener("click", () => {
    pracAdminCategoryIconDraft = null;
    pracAdminCategoryUI = { editingCategoryId: null, newCategoryOpen: true };
    renderPracticeAdminCategoryList();
  });

  // Switching the Subjects tab's category picker re-scopes
  // getPracticeAdminSubjects()/setPracticeAdminSubjects() to the chosen
  // category (same activePracticeCategoryId the Practice Panel and
  // Statistics page read) and re-renders that category's subject list.
  qs("#pa-admin-category-select")?.addEventListener("change", (e) => {
    activePracticeCategoryId = e.target.value;
    pracAdminUI = { openSubjectId: null, editingSubjectId: null, newSubjectOpen: false, editingTopic: null, newTopicForSubject: null };
    renderPracticeAdminSubjectList();
    // Keep the AGQ tab's own category picker (and everything it drives —
    // Subject Order, Topic-wise Target) in sync with this same shared
    // activePracticeCategoryId, in case the user switches tabs next.
    const agqSelect = document.getElementById("agq-category-select");
    if (agqSelect) {
      agqSelect.value = activePracticeCategoryId;
      const firstSubject = (getPracticeAdminSubjects() || [])[0] || null;
      if (typeof currentGenSubjectId !== "undefined") {
        currentGenSubjectId = firstSubject?.id || null;
        currentGenTopicId = firstSubject?.topics?.[0]?.id || null;
      }
      if (typeof renderSubjectList === "function") renderSubjectList(document.getElementById("subjectOrderList"), false);
      if (typeof populateTargetSubjectSelect === "function") populateTargetSubjectSelect();
      if (typeof renderTopicTargetList === "function") renderTopicTargetList();
    }
  });

  PracticeMCQBuilder.bindEvents();
}

/* ---------- Generic nav + wiring ---------- */
function initSpaNav() {
  qsa("[data-spa-nav]").forEach((el) => {
    el.addEventListener("click", (e) => {
      e.preventDefault();
      const target = el.getAttribute("data-spa-nav");
      // Icon buttons styled as a plain "Back" chevron (as opposed to
      // the Home icon, or a normal forward link/card) should return to
      // wherever the user came from, not their hardcoded data-spa-nav
      // target — that target only ever exists as a fallback for when
      // there's no history (e.g. a direct link or a refreshed page).
      if (el.classList.contains("icon-btn--back")) {
        goBackView(target);
      } else {
        // Any explicit jump to Home (via the Home icon, dashboard
        // cards, etc.) is a deliberate return to the root — clear the
        // back-stack so a later Back press doesn't replay stale views.
        navigateToView(target, target === "home" ? { resetHistory: true } : undefined);
      }
    });
  });

  // Practice hub cards that aren't wired to a real view yet (Highlights
  // Question / Vocabulary Master / Current Affairs) — just a heads-up
  // toast for now instead of a dead link.
  qsa("[data-practice-soon]").forEach((el) => {
    el.addEventListener("click", () => {
      showToast(t("practice.comingSoon"), "info");
    });
  });
}

document.addEventListener("DOMContentLoaded", () => {
  // Seed a base history entry for the initial Home view so the very
  // first press of the device Back button has something real to pop
  // against (see the popstate listener above showView) instead of
  // navigating away from the app on the first tap.
  history.replaceState({ view: "home" }, "", location.href);

  initGeneratorView();
  initLiveExamView();
  initCentralLiveExam();
  initEnrollModal();
  initStatisticsView();
  initPrintView();
  initPdfSettingsPanel();
  initSpaNav();
  initPracticeView();
  initPracticeAdminPanel();
  initPracticeInterestModal();

  // Worker/KV-backed Practice Subject/Topic tree: pull the current
  // manifest once at startup so the Practice Panel (and Practice Admin
  // Panel, for the admin) reflect the real server-side list instead of
  // only whatever was cached in this browser's localStorage or the
  // built-in defaultPracticeSubjects() fallback. If the initial view on
  // load happens to already be Practice/Practice Admin (e.g. a refresh),
  // re-render once this resolves — same "instant local render, refresh
  // in background" pattern as refreshPracticeAndRerenderPanel/Admin used
  // on in-app navigation.
  refreshPracticeManifest().then((changed) => {
    if (!changed) return;
    const page = document.body.getAttribute("data-page");
    if (page === "practice") renderPracticeCategoryList();
    else if (page === "practice-admin") renderPracticeAdminSubjectList();
    else if (page === "statistics") renderBcsPreliminaryStats();
  });

  // Supabase-backed Live Exam data: pull the current state once so the
  // Home/Live Exam/Admin views have real Subject/Exam/Member/Enrollment
  // data instead of only whatever was cached in localStorage, then start
  // listening for realtime changes so every open tab stays in sync
  // (new exams, pushed questions, incoming submissions, new signups).
  pullCentralExamStateFromSupabase();
  subscribeCentralExamRealtime();

  // If a completed/active exam already exists (e.g. page was refreshed
  // mid-exam), resume it instead of showing a stale question-1 state.
  const existing = restoreExamSession();
  if (existing && existing.status !== "completed" && (window.location.hash === "#exam")) {
    enterLiveExam();
  }
});

